import{_ as s,o as a,c as n,a3 as o}from"./chunks/framework.Cc-oPviL.js";const g=JSON.parse('{"title":"01 · 复杂度与数组、链表","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/dsa/01.md","filePath":"bagu/dsa/01.md"}'),e={name:"bagu/dsa/01.md"};function l(i,t,r,p,d,c){return a(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="_01-·-复杂度与数组、链表" tabindex="-1">01 · 复杂度与数组、链表 <a class="header-anchor" href="#_01-·-复杂度与数组、链表" aria-label="Permalink to &quot;01 · 复杂度与数组、链表&quot;">​</a></h1><blockquote><p>复杂度是这一模块的&quot;度量尺&quot;，数组和链表是&quot;最基础的两个极端&quot;。看懂它们的取舍，后面的所有结构都只是&quot;在这两端之间做混合&quot;。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><ul><li><strong>复杂度</strong>：不看秒数，看&quot;数据量翻倍时，耗时怎么变&quot;。</li><li><strong>数组 vs 链表</strong>：一个把数据摆得紧凑、靠位置直接算地址；一个把数据撒开、靠指针一个个跳。</li></ul><h2 id="生活类比-连排座位-vs-寻宝纸条" tabindex="-1">生活类比：连排座位 vs 寻宝纸条 <a class="header-anchor" href="#生活类比-连排座位-vs-寻宝纸条" aria-label="Permalink to &quot;生活类比：连排座位 vs 寻宝纸条&quot;">​</a></h2><p><strong>数组 = 电影院的连排座位</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[A][B][C][D][E][F]</span></span>
<span class="line"><span> 0  1  2  3  4  5</span></span></code></pre></div><ul><li>知道第 3 排在哪，走几步就到 &gt; <strong>随机访问 O(1)</strong></li><li>中间要插一个人 &gt; 后面所有人往后挪 &gt; <strong>插入 O(n)</strong></li><li>座位是连着的，一排人坐一起，服务员一次能服务好几个 &gt; <strong>缓存友好</strong></li></ul><p><strong>链表 = 寻宝游戏</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[A|&gt;]  [B|&gt;]  [C|&gt;]  [D|&gt;]  [E|∅]</span></span>
<span class="line"><span> ^      ^</span></span>
<span class="line"><span> 每张纸条写着下一张在哪</span></span></code></pre></div><ul><li>想找第 4 张 &gt; 必须从第 1 张开始，一张张跟 &gt; <strong>查找 O(n)</strong></li><li>想在 B 后面插一张 &gt; 只需改两个指针 &gt; <strong>插入 O(1)</strong>（前提是你已经站在 B 那里）</li><li>每张纸条藏在不同地方，跑来跑去很费腿 &gt; <strong>缓存不友好</strong></li></ul><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、复杂度-怎么-看出来" tabindex="-1">一、复杂度：怎么&quot;看出来&quot; <a class="header-anchor" href="#一、复杂度-怎么-看出来" aria-label="Permalink to &quot;一、复杂度：怎么&quot;看出来&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>O(1)     常数      哈希查找、数组按下标访问</span></span>
<span class="line"><span>O(log n) 对数      二分、平衡树查找      &lt; 数据翻倍，只多一步</span></span>
<span class="line"><span>O(n)     线性      遍历、链表查找</span></span>
<span class="line"><span>O(n log n)         快排、归并           &lt; 排序的下界</span></span>
<span class="line"><span>O(n²)    平方      双重循环、冒泡</span></span>
<span class="line"><span>O(2ⁿ)    指数      暴力枚举子集</span></span></code></pre></div><p><strong>看出来的三个口诀</strong>：</p><ol><li><strong>看到&quot;每次砍一半&quot;&gt; log n</strong>（二分、树）</li><li><strong>看到&quot;单层循环&quot;&gt; n</strong>，<strong>&quot;嵌套两层&quot;&gt; n²</strong></li><li><strong>看到&quot;递归里每次分成两半各做一遍&quot;&gt; n log n</strong>（归并、快排）</li></ol><p><strong>只保留最高阶，忽略常数</strong>：<code>3n² + 100n + 5</code> &gt; <code>O(n²)</code>。因为 n 足够大时，低阶项和常数可以忽略。</p><p><strong>但工程里常数很重要</strong>：同样是 O(n log n)，快排通常比归并快 2~3 倍（缓存友好、常数小）。所以面试答&quot;复杂度相同&quot;之后，补一句&quot;实际快排更快，因为内存访问模式更好&quot;，会很加分。</p><h3 id="二、数组的地址计算-为什么是-o-1" tabindex="-1">二、数组的地址计算（为什么是 O(1)） <a class="header-anchor" href="#二、数组的地址计算-为什么是-o-1" aria-label="Permalink to &quot;二、数组的地址计算（为什么是 O(1)）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数组起始地址 base = 0x1000，每个元素 4 字节</span></span>
<span class="line"><span>访问 a[3]：</span></span>
<span class="line"><span>  地址 = base + 3 × 4 = 0x1000 + 12 = 0x100C</span></span></code></pre></div><p><strong>一次乘加就出地址</strong>，不需要遍历。这就是 O(1) 的本质——<strong>不是&quot;快&quot;，是&quot;计算量不随 n 增长&quot;</strong>。</p><p><strong>二维数组</strong>：<code>a[i][j]</code> 的地址 = <code>base + (i × 列数 + j) × 元素大小</code>。所以按行遍历（<code>i</code> 在外层）比按列遍历快得多——因为按列遍历会不断跳过整行，缓存命中率极低。</p><h3 id="三、链表的几种形态" tabindex="-1">三、链表的几种形态 <a class="header-anchor" href="#三、链表的几种形态" aria-label="Permalink to &quot;三、链表的几种形态&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单链表：    A &gt; B &gt; C &gt; ∅            只能前进</span></span>
<span class="line"><span>双链表：    A ⇄ B ⇄ C &gt; ∅            能前进能后退（多一个指针，空间翻倍）</span></span>
<span class="line"><span>循环链表：  A &gt; B &gt; C &gt; A            尾接回头</span></span></code></pre></div><p><strong>哨兵节点（dummy head）</strong>：在头部加一个空节点，让&quot;在头部插入&quot;和&quot;在中间插入&quot;的代码统一，不用特判。这是写链表题的实用技巧。</p><h3 id="四、数组-vs-链表-完整对比" tabindex="-1">四、数组 vs 链表：完整对比 <a class="header-anchor" href="#四、数组-vs-链表-完整对比" aria-label="Permalink to &quot;四、数组 vs 链表：完整对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>数组</th><th>链表</th><th>说明</th></tr></thead><tbody><tr><td>按下标访问</td><td><strong>O(1)</strong></td><td>O(n)</td><td>数组的核心优势</td></tr><tr><td>头部插入</td><td>O(n)</td><td><strong>O(1)</strong></td><td>数组要整体后移</td></tr><tr><td>尾部插入</td><td><strong>O(1)</strong> 摊销</td><td>O(1)</td><td>数组扩容时是 O(n)，但摊销后 O(1)</td></tr><tr><td>中间插入</td><td>O(n)</td><td>O(1)*</td><td>*前提是已定位到位置，找位置本身是 O(n)</td></tr><tr><td>删除</td><td>O(n)</td><td>O(1)*</td><td>同上</td></tr><tr><td>查找值</td><td>O(n)</td><td>O(n)</td><td>都要遍历（除非有序）</td></tr><tr><td>内存开销</td><td>小（无指针）</td><td>大（每节点 1~2 个指针）</td><td></td></tr><tr><td>缓存友好</td><td><strong>好</strong></td><td>差</td><td>这是实测差距的主要来源</td></tr><tr><td>扩容</td><td>需重新分配 + 拷贝</td><td>天然支持</td><td></td></tr></tbody></table><p><strong>&quot;中间插入 O(1)&quot;是个陷阱</strong>：你只知道&quot;改指针是 O(1)&quot;，但<strong>找到那个位置要 O(n)</strong>。所以链表插入的完整复杂度是 O(n)。面试常在这里挖坑。</p><h3 id="五、为什么数组实测快这么多-接-os-篇" tabindex="-1">五、为什么数组实测快这么多（接 OS 篇） <a class="header-anchor" href="#五、为什么数组实测快这么多-接-os-篇" aria-label="Permalink to &quot;五、为什么数组实测快这么多（接 OS 篇）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CPU 读内存不是按字节读，是按&quot;缓存行&quot;（通常 64 字节）读</span></span>
<span class="line"><span>  &gt; 读 a[0] 时，a[1]~a[15] 也一起进了缓存</span></span>
<span class="line"><span>  &gt; 遍历数组时，后面 15 次访问全部命中缓存</span></span>
<span class="line"><span></span></span>
<span class="line"><span>链表节点散落在堆上</span></span>
<span class="line"><span>  &gt; 读 A 节点时，B 节点在完全不同的地址</span></span>
<span class="line"><span>  &gt; 每次跳转都是一次缓存未命中 &gt; 等内存（约 100 个时钟周期）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>差距量化：</span></span>
<span class="line"><span>  数组遍历 1 亿个元素：约 0.1 秒</span></span>
<span class="line"><span>  链表遍历 1 亿个元素：约 1~2 秒（10 倍以上差距）</span></span>
<span class="line"><span>  虽然都是 O(n)</span></span></code></pre></div><p><strong>这就是&quot;复杂度相同但实际差 10 倍&quot;的经典案例</strong>。也是为什么 Java 的 <code>ArrayList</code> 在大多数场景下比 <code>LinkedList</code> 快——尽管教科书说链表插入快。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果数组不连续" tabindex="-1">反事实 1：如果数组不连续 <a class="header-anchor" href="#反事实-1-如果数组不连续" aria-label="Permalink to &quot;反事实 1：如果数组不连续&quot;">​</a></h3><p>那就不叫数组了。<strong>&quot;连续&quot;是数组能 O(1) 访问的唯一前提</strong>——因为只有连续，才能用&quot;基址 + 偏移&quot;算出地址。一旦允许分散，就必须额外存映射关系（那就是哈希表或页表了）。</p><h3 id="反事实-2-如果链表节点连续" tabindex="-1">反事实 2：如果链表节点连续 <a class="header-anchor" href="#反事实-2-如果链表节点连续" aria-label="Permalink to &quot;反事实 2：如果链表节点连续&quot;">​</a></h3><p>那它就成了数组（或者说&quot;用数组实现的链表&quot;）。链表的全部价值就在于&quot;<strong>插入删除不影响其他元素的位置</strong>&quot;——而这就要求节点不能连续（否则挪动一个会影响后面所有）。</p><h3 id="反事实-3-如果数组不预留空间" tabindex="-1">反事实 3：如果数组不预留空间 <a class="header-anchor" href="#反事实-3-如果数组不预留空间" aria-label="Permalink to &quot;反事实 3：如果数组不预留空间&quot;">​</a></h3><p>每次插入都重新分配 + 拷贝，插入 n 次就是 O(n²)。所以 <code>ArrayList</code> 会<strong>按 1.5 倍扩容</strong>，用&quot;浪费一点空间&quot;换&quot;摊销 O(1)&quot;。</p><p><strong>摊销分析</strong>：扩容一次 O(n)，但平均到 n 次插入上，每次是 O(1)。这就是&quot;摊销 O(1)&quot;的含义。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：数组和链表的区别？</strong></p><blockquote><p>别只答&quot;一个连续一个不连续&quot;。要按操作答：随机访问数组 O(1)、链表 O(n)；插入删除链表理论上快但定位仍 O(n)；<strong>再加一句实测差距来自缓存局部性</strong>——这句是区分度所在。</p></blockquote><p><strong>Q：为什么数组随机访问是 O(1)？</strong></p><blockquote><p>因为地址可以算出来：<code>base + index × size</code>，一次乘加，与 n 无关。链表必须从头遍历，因为节点地址不连续、无法计算。</p></blockquote><p><strong>Q：链表插入是 O(1) 吗？</strong></p><blockquote><p>分两种说法：<strong>&quot;已知前驱节点时，插入本身 O(1)&quot;</strong>；<strong>&quot;从头找位置再插入是 O(n)&quot;</strong>。完整答案要区分这两层，否则会被追问打脸。</p></blockquote><p><strong>Q：ArrayList 扩容为什么是 1.5 倍而不是 2 倍？</strong></p><blockquote><p>1.5 倍（Java）比 2 倍（C++ vector）更&quot;温和&quot;：2 倍容易导致&quot;上一次扩容释放的空间 + 这次需要的空间&quot;都装不下（因为总和超过可用内存），1.5 倍能让释放的空间被复用。这是经验性的工程取舍，不是理论最优。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数组和链表区别？</span></span>
<span class="line"><span>  &gt; 数组为什么 O(1)？（地址可计算）</span></span>
<span class="line"><span>    &gt; 那链表为什么不行？（不连续，地址不可算）</span></span>
<span class="line"><span>      &gt; 链表插入真的 O(1) 吗？（定位仍 O(n)）</span></span>
<span class="line"><span>        &gt; 既然链表插入快，为什么实际更慢？（缓存不友好 + 指针开销）</span></span>
<span class="line"><span>          &gt; 那什么时候真的该用链表？（频繁在已知位置插入删除，如 LRU 的双向链表）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/02">虚拟内存：让每个程序都以为自己独占一台机器</a>：缓存行、TLB、内存布局，是&quot;数组实测更快&quot;的底层原因</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/dsa/02">栈、队列与哈希表</a>：栈和队列都可以用数组或链表实现，选哪个取决于操作模式</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/dsa/03">树与堆</a>：完全二叉树用数组存储（下标 i 的孩子是 2i+1 和 2i+2），这就是堆的实现方式</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/01">索引与 B+ 树</a>：B+ 树的叶子节点用链表串联，就是为了范围查询能顺序扫</li><li><strong>&gt; 影响</strong> 工程实践：Java <code>ArrayList</code> vs <code>LinkedList</code>、Redis 的 quicklist（链表套数组）、Kafka 的日志段（顺序写 + 稀疏索引）</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：遍历 1 亿个元素，数组和链表都是 O(n)，为什么实测差 10 倍？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为<strong>CPU 缓存</strong>。</p><p>CPU 读内存按&quot;缓存行&quot;（64 字节）为单位。数组连续，读 <code>a[0]</code> 时会把 <code>a[0]</code> 到 <code>a[15]</code>（假设 int）一起载入缓存，后面 15 次访问全部命中，几乎不花时间。</p><p>链表节点分散在堆的各个角落，每次 <code>node = node-&gt;next</code> 都跳到新地址，<strong>大概率缓存未命中</strong>，必须去主存取（约 100 个时钟周期）。而且 CPU 的硬件预取器能识别&quot;顺序访问&quot;提前加载，对随机跳转完全无能为力。</p><p>所以：<strong>复杂度衡量的是&quot;操作次数&quot;，不衡量&quot;每次操作多贵&quot;</strong>。缓存未命中的代价，是复杂度分析里被省略的那个常数。</p></details><p><strong>Q2：<code>ArrayList</code> 的 add 是 O(1) 还是 O(n)？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>摊销 O(1)</strong>。</p><ul><li>大多数情况下直接放到末尾，O(1)。</li><li>容量满了要扩容：申请 1.5 倍的新数组 + 拷贝全部元素，这一次是 O(n)。</li></ul><p>但扩容不是每次都发生。假设从容量 1 开始翻倍，n 次插入总共拷贝约 2n 次，平均到每次是 O(1)。这叫<strong>摊销分析</strong>。</p><p>注意：<strong>摊销 O(1) 不代表&quot;每次都很快&quot;</strong>。偶尔会有一次明显的卡顿（扩容），这对延迟敏感的系统是问题——所以有时会预分配容量（<code>new ArrayList&lt;&gt;(10000)</code>）。</p></details><p><strong>Q3：什么场景下链表真的比数组好？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>必须同时满足两个条件：<strong>① 频繁在已知位置插入/删除；② 不需要随机访问</strong>。</p><p>典型场景：</p><ol><li><strong>LRU 缓存</strong>：哈希表 + 双向链表。哈希表 O(1) 定位节点，链表 O(1) 把节点移到头部/删除。</li><li><strong>操作系统的进程就绪队列</strong>：进程频繁进出队列，不需要按位置访问。</li><li><strong>大对象的容器</strong>：元素本身很大（拷贝代价高），链表只移动指针。</li></ol><p>反例（常见误用）：<code>LinkedList</code> 做&quot;频繁随机插入&quot;——每次插入前都要遍历找位置，实际比 <code>ArrayList</code> 慢得多。<strong>Java 官方文档自己都说 <code>LinkedList</code> 很少是最佳选择</strong>。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;电影院座位&quot;会让人以为数组插入永远慢</strong>。尾部追加是摊销 O(1)，只有中间插入才 O(n)。</li><li><strong>&quot;链表插入 O(1)&quot;漏掉了&quot;定位&quot;这一步</strong>。完整代价是 O(n)，除非你已经持有前驱指针。</li><li><strong>复杂度不是&quot;实际耗时&quot;</strong>。同样的 O(n log n)，快排和归并可能差 2~3 倍；同样的 O(n)，数组和链表差 10 倍。</li><li><strong><code>ArrayList</code> 扩容 1.5 倍 vs <code>vector</code> 2 倍</strong>：没有绝对优劣，1.5 倍更容易复用已释放的内存，2 倍扩容次数更少。别把某一个说成&quot;标准答案&quot;。</li><li><strong>链表不一定省内存</strong>。每个节点多一个指针（8 字节），如果存的是 int（4 字节），空间开销直接翻 3 倍。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能说出 O(1) / O(log n) / O(n) / O(n log n) / O(n²) 各自的典型场景</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能&quot;看出来&quot;复杂度：给一段代码能说出是 O(n) 还是 O(n²) 还是 O(n log n)</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能写出数组地址计算公式，并解释&quot;为什么随机访问是 O(1)&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能完整对比数组和链表的 6 种操作复杂度，并指出&quot;链表插入 O(1)&quot;的陷阱</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能用缓存行解释&quot;为什么数组实测比链表快 10 倍&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能解释摊销 O(1) 的含义，并说出预分配容量的意义</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 能举出一个&quot;链表真的比数组好&quot;的场景，并说清原因</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="7"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,63)])])}const h=s(e,[["render",l]]);export{g as __pageData,h as default};
